def anisotropic_member_scientific_ordinal(*, mass_x: Decimal, mass_y: Decimal, cross_coupling_gamma: Decimal) -> int:
    for index, values in enumerate(ANISOTROPIC_MEMBER_NUMERIC_PARAMETERS):
        if (mass_x, mass_y, cross_coupling_gamma) == tuple(Decimal(value) for value in values):
            return index
    raise ValueError("anisotropic member lacks a frozen original scientific seed input")


def canonical_model_scientific_ordinal(*, mass_m: Decimal, q: int, alpha_tilde: Decimal) -> int:
    for index, values in enumerate(CANONICAL_MODEL_NUMERIC_PARAMETERS):
        if (mass_m, q, alpha_tilde) == (Decimal(values[0]), values[1], Decimal(values[2])):
            return index
    raise ValueError("canonical numerical model lacks a frozen original scientific seed input")


def anisotropic_scientific_seed_sha256(*, member_ordinal: int, stage_ordinal: int, alpha_x_index: int, alpha_y_index: int, history_ordinal: int, seed_index: int, view_ordinal: int) -> str:
    key = (member_ordinal, stage_ordinal, alpha_x_index, alpha_y_index, history_ordinal, seed_index, view_ordinal)
    if any(type(value) is not int for value in key) or key not in _ANISOTROPIC_SEEDS:
        raise ValueError("anisotropic numerical task lacks a frozen original scientific seed input")
    return _ANISOTROPIC_SEEDS[key]


def qualification_episode_scientific_seed_sha256(*, role_ordinal: int, case_ordinal: int, view_ordinal: int, seed_index: int) -> str:
    key = role_ordinal, case_ordinal, view_ordinal, seed_index
    if any(type(value) is not int for value in key) or key not in _EPISODE_SEEDS:
        raise ValueError("qualification episode lacks a frozen original scientific seed input")
    return _EPISODE_SEEDS[key]
